import { useEffect, useState, type CSSProperties } from 'react';
import { useUiLanguage } from '../i18n/UiLanguage.tsx';
import { usePrefersReducedMotion } from '../usePrefersReducedMotion.ts';

interface Props {
  /** `null` = nothing to show yet (`emptyText` is shown). */
  src: string | null;
  alt: string;
  emptyText: string;
  /** Dominant color of the asset: background while the image downloads. */
  color?: string | undefined;
  /** Blurred thumbnail as a data URI (generated by the API on upload): background while the image downloads. */
  placeholder?: string | undefined;
  /**
   * Short video that plays muted and looped over `src` (which becomes its poster). With "reduce motion" it does not
   * start on its own: it shows the poster and the browser controls to play it (WCAG 2.2.2).
   */
  video?: string | null | undefined;
  /** `span` inside a button (the hero thumbnails): a <button> only allows inline content. */
  as?: 'div' | 'span';
}

// Only base64 image data URIs: the value goes inside url("…") and must not be able to break the CSS declaration.
const SAFE_PLACEHOLDER = /^data:image\/[a-z]+;base64,[a-z0-9+/=]+$/i;

/**
 * Thumbnail with a waiting background and a notice if the image or video fails to load (cover, hero items). The image
 * only downloads when it nears the screen (`loading="lazy"`): with 50 thumbnails in the hero grid it matters.
 */
export function ImagePreview({ src, alt, emptyText, color, placeholder, video, as: Root = 'div' }: Props) {
  const { t } = useUiLanguage();
  const [broken, setBroken] = useState(false);
  const reducedMotion = usePrefersReducedMotion();

  // A new image deserves another preview attempt.
  useEffect(() => setBroken(false), [src, video]);

  const background: CSSProperties = {
    backgroundColor: color,
    backgroundImage: placeholder && SAFE_PLACEHOLDER.test(placeholder) ? `url("${placeholder}")` : undefined,
  };

  return (
    <Root className="image-field-preview" style={background}>
      {video && !broken ? (
        // Muted and inline: that is what allows autoplay, same as on the home page. `key`: changing `autoPlay` on an
        // already mounted video does not stop it; mounting it again does.
        <video
          key={String(reducedMotion)}
          src={video}
          poster={src ?? undefined}
          aria-label={alt}
          muted
          loop
          playsInline
          autoPlay={!reducedMotion}
          controls={reducedMotion}
          onError={() => setBroken(true)}
        />
      ) : src && !broken ? (
        <img src={src} alt={alt} loading="lazy" decoding="async" onError={() => setBroken(true)} />
      ) : (
        <span className="image-field-empty">{broken ? t('image.previewFailed') : emptyText}</span>
      )}
    </Root>
  );
}
